   127  readstat_missingness_t spss_missingness_for_info(spss_varinfo_t *info) {
   128      readstat_missingness_t missingness;
   129      memset(&missingness, '\0', sizeof(readstat_missingness_t));
   130
   131      if (info->missing_range) {
   132          missingness.missing_ranges_count++;
   133          missingness.missing_ranges[0] = spss_boxed_missing_value(info, 0);
   134          missingness.missing_ranges[1] = spss_boxed_missing_value(info, 1);
   135
   136          if (info->n_missing_values == 3) {
   137              missingness.missing_ranges_count++;
   138              missingness.missing_ranges[2] = missingness.missing_ranges[3] = spss_boxed_missing_value(info, 2);
   139          }
   140      } else if (info->n_missing_values > 0) {
   141          missingness.missing_ranges_count = info->n_missing_values;
   142          int i=0;
   143          for (i=0; i<info->n_missing_values; i++) {
   144              missingness.missing_ranges[2*i] = missingness.missing_ranges[2*i+1] = spss_boxed_missing_value(info, i);
   145          }
   146      }
   147      return missingness;
   148  }
