   150  readstat_variable_t *spss_init_variable_for_info(spss_varinfo_t *info, int index_after_skipping,
   151          iconv_t converter) {
   152      readstat_variable_t *variable = calloc(1, sizeof(readstat_variable_t));
   153
   154      variable->index = info->index;
   155      variable->index_after_skipping = index_after_skipping;
   156      variable->type = info->type;
   157      if (info->string_length) {
   158          variable->storage_width = info->string_length;
   159      } else {
   160          variable->storage_width = 8 * info->width;
   161      }
   162
   163      if (info->longname[0]) {
   164          readstat_convert(variable->name, sizeof(variable->name),
   165                  info->longname, sizeof(info->longname), converter);
   166      } else {
   167          readstat_convert(variable->name, sizeof(variable->name),
   168                  info->name, sizeof(info->name), converter);
   169      }
   170      if (info->label) {
   171          snprintf(variable->label, sizeof(variable->label), "%s", info->label);
   172      }
   173
   174      spss_format(variable->format, sizeof(variable->format), &info->print_format);
   175
   176      variable->missingness = spss_missingness_for_info(info);
   177      variable->measure = info->measure;
   178      if (info->display_width) {
   179          variable->display_width = info->display_width;
   180      } else {
   181          variable->display_width = info->print_format.width;
   182      }
   183
   184      return variable;
   185  }
